UPDATE wms_picking_task
task_no = #{taskNo}, shipment_order_id = #{shipmentOrderId}, warehouse_id = #{warehouseId}, picker = #{picker}, task_type = #{taskType}, picking_mode = #{pickingMode}, total_items = #{totalItems}, total_quantity = #{totalQuantity}, picked_items = #{pickedItems}, picked_quantity = #{pickedQuantity}, status = #{status}, priority = #{priority}, assign_time = #{assignTime}, start_time = #{startTime}, finish_time = #{finishTime}, remark = #{remark}, update_time = NOW()
