mapper.select:
SELECT

FROM wms_picking_task pt
LEFT JOIN wms_shipment_order so ON pt.shipment_order_id = so.id
LEFT JOIN wms_user u ON pt.picker = u.username

    AND pt.warehouse_id = #{warehouseId}
    AND pt.shipment_order_id = #{shipmentOrderId}
    AND pt.picker = #{picker}
    AND pt.status = #{status}
    AND pt.priority = #{priority}

ORDER BY pt.priority ASC, pt.create_time DESC

